package com.rgbcursor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayDeque;
import java.util.Iterator;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class RgbTrailOverlay extends Overlay
{
	private static final class TrailPoint
	{
		final int x;
		final int y;
		final long time;

		TrailPoint(int x, int y, long time)
		{
			this.x = x;
			this.y = y;
			this.time = time;
		}
	}

	private final Client client;
	private final RgbCursorPlugin plugin;
	private final RgbCursorConfig config;
	private final ArrayDeque<TrailPoint> points = new ArrayDeque<>();

	@Inject
	RgbTrailOverlay(Client client, RgbCursorPlugin plugin, RgbCursorConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(Overlay.PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.trailEnabled())
		{
			points.clear();
			return null;
		}

		final long now = System.nanoTime();
		final long lifetime = config.trailDuration() * 1_000_000L;

		final Point mouse = client.getMouseCanvasPosition();
		if (mouse != null && mouse.getX() >= 0 && mouse.getY() >= 0)
		{
			TrailPoint last = points.peekLast();
			if (last == null || last.x != mouse.getX() || last.y != mouse.getY())
			{
				points.addLast(new TrailPoint(mouse.getX(), mouse.getY(), now));
			}
		}

		while (!points.isEmpty() && now - points.peekFirst().time > lifetime)
		{
			points.removeFirst();
		}

		if (points.size() < 2)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		final float headHue = plugin.getHue(now);
		final float spread = config.trailRainbowSpread() / 100f;
		final float saturation = config.saturation() / 100f;
		final int width = config.trailWidth();

		Iterator<TrailPoint> it = points.iterator();
		TrailPoint prev = it.next();
		while (it.hasNext())
		{
			TrailPoint cur = it.next();
			// 0 at the cursor, 1 where the trail has fully faded
			float age = Math.min(1f, (float) (now - cur.time) / lifetime);
			float life = 1f - age;

			int rgb = Color.HSBtoRGB(headHue - spread * age, saturation, 1f) & 0xFFFFFF;
			int alpha = Math.round(255 * life);
			g.setColor(new Color((alpha << 24) | rgb, true));
			g.setStroke(new BasicStroke(Math.max(1f, width * life), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(prev.x, prev.y, cur.x, cur.y);
			prev = cur;
		}

		return null;
	}
}

package com.rgbcursor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Toolkit;
import java.awt.geom.AffineTransform;
import java.awt.geom.Area;
import java.awt.geom.Path2D;
import java.awt.image.BaseMultiResolutionImage;
import java.awt.image.BufferedImage;
import java.awt.image.ConvolveOp;
import java.awt.image.Kernel;
import java.util.Arrays;
import net.runelite.client.plugins.customcursor.CustomCursorPlugin;
import net.runelite.client.util.ImageUtil;

/**
 * Pre-renders one full color cycle of the cursor as native {@link Cursor}s,
 * so animating is just picking the next one instead of creating cursors every frame.
 */
final class CursorFrames
{
	static final int FRAME_COUNT = 60;

	// Outer edge (border included) of the macOS pointer in points at its native 17pt height, tip at (0, 0)
	private static final double[] ARROW_X = {0, 0, 3.0, 4.9, 7.8, 6.1, 9.8};
	private static final double[] ARROW_Y = {0, 13.5, 11.4, 16.6, 16.0, 10.8, 10.8};
	private static final double ARROW_HEIGHT = 16.6;
	private static final double ARROW_WIDTH = 9.8;

	private static final Color SHADOW = new Color(0, 0, 0, 110);

	/**
	 * A cursor source split into a layer that gets recolored and a fixed layer drawn beneath it
	 * (the arrow's border and drop shadow), so the border keeps its color instead of turning rainbow.
	 */
	private static final class Layers
	{
		BufferedImage under;
		BufferedImage tint;
	}

	private CursorFrames()
	{
	}

	static Cursor[] build(CursorShape shape, RgbCursorEffect effect, int size, float saturation, boolean outline, BorderColor borderColor)
	{
		final Toolkit toolkit = Toolkit.getDefaultToolkit();
		final Point hotspot = new Point();
		final BufferedImage[] lo = render(shape, effect, size, saturation, outline, borderColor, 1, hotspot);
		// A 2x set lets HiDPI (Retina) screens show a sharp cursor instead of an upscaled one
		final BufferedImage[] hi = render(shape, effect, size, saturation, outline, borderColor, 2, new Point());

		final Cursor[] frames = new Cursor[FRAME_COUNT];
		for (int f = 0; f < FRAME_COUNT; f++)
		{
			// Place on a canvas of the platform's preferred cursor size so it isn't rescaled badly
			Dimension best = toolkit.getBestCursorSize(lo[f].getWidth(), lo[f].getHeight());
			int w = Math.max(best.width, lo[f].getWidth());
			int h = Math.max(best.height, lo[f].getHeight());
			BaseMultiResolutionImage img = new BaseMultiResolutionImage(onCanvas(lo[f], w, h), onCanvas(hi[f], w * 2, h * 2));
			frames[f] = toolkit.createCustomCursor(img, hotspot, "rgb-cursor-" + f);
		}
		return frames;
	}

	/**
	 * Renders the recolored frames at the given pixel scale; {@code hotspot} receives the click point in 1x pixels.
	 */
	static BufferedImage[] render(CursorShape shape, RgbCursorEffect effect, int size, float saturation, boolean outline, BorderColor borderColor, int scale, Point hotspot)
	{
		final Layers layers = shape.getResource() == null
			? renderArrow(size, outline, borderColor, scale, hotspot)
			: loadImage(shape.getResource(), scale);
		final BufferedImage source = layers.tint;
		final int w = source.getWidth();
		final int h = source.getHeight();
		final int[] srcPx = source.getRGB(0, 0, w, h, null, 0, w);

		// Recolor by brightness so shading and dark outlines survive. Scale against a high percentile rather than
		// the single brightest pixel, otherwise one highlight leaves the rest of a sprite (e.g. the scimitar) dim.
		final float[] value = new float[srcPx.length];
		final float[] opaque = new float[srcPx.length];
		int opaqueCount = 0;
		for (int i = 0; i < srcPx.length; i++)
		{
			int p = srcPx[i];
			value[i] = (0.299f * ((p >> 16) & 0xFF) + 0.587f * ((p >> 8) & 0xFF) + 0.114f * (p & 0xFF)) / 255f;
			if ((p >>> 24) > 0)
			{
				opaque[opaqueCount++] = value[i];
			}
		}
		Arrays.sort(opaque, 0, opaqueCount);
		final float ref = opaqueCount > 0 ? opaque[(int) (opaqueCount * 0.9f)] : 0f;
		if (ref > 0f)
		{
			for (int i = 0; i < value.length; i++)
			{
				value[i] = (float) Math.pow(Math.min(1f, value[i] / ref), 0.75);
			}
		}

		final BufferedImage[] frames = new BufferedImage[FRAME_COUNT];

		for (int f = 0; f < FRAME_COUNT; f++)
		{
			final float phase = (float) f / FRAME_COUNT;
			float brightness = 1f;
			if (effect == RgbCursorEffect.BREATHE)
			{
				// Two slow pulses per color cycle, never fully dark
				brightness = 0.6f + 0.4f * (float) (0.5 + 0.5 * Math.cos(phase * 4 * Math.PI));
			}

			final int[] px = new int[w * h];
			for (int y = 0; y < h; y++)
			{
				for (int x = 0; x < w; x++)
				{
					int i = y * w + x;
					int alpha = srcPx[i] >>> 24;
					if (alpha == 0)
					{
						continue;
					}

					// Hue runs diagonally across the cursor and scrolls with the phase in wave mode
					float hue = effect == RgbCursorEffect.WAVE ? phase - (float) (x + y) / (w + h) : phase;
					int rgb = Color.HSBtoRGB(hue, saturation, value[i] * brightness) & 0xFFFFFF;
					px[i] = (alpha << 24) | rgb;
				}
			}

			BufferedImage frame = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = frame.createGraphics();
			if (layers.under != null)
			{
				g.drawImage(layers.under, 0, 0, null);
			}
			BufferedImage tinted = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			tinted.setRGB(0, 0, w, h, px, 0, w);
			g.drawImage(tinted, 0, 0, null);
			g.dispose();
			frames[f] = frame;
		}

		return frames;
	}

	private static BufferedImage onCanvas(BufferedImage img, int w, int h)
	{
		BufferedImage canvas = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		g.drawImage(img, 0, 0, null);
		g.dispose();
		return canvas;
	}

	private static Layers loadImage(String resource, int scale)
	{
		BufferedImage img = ImageUtil.loadImageResource(CustomCursorPlugin.class, resource);
		// Nearest-neighbour upscale keeps the pixel-art sprites crisp at 2x
		BufferedImage argb = new BufferedImage(img.getWidth() * scale, img.getHeight() * scale, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = argb.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(img, 0, 0, argb.getWidth(), argb.getHeight(), null);
		g.dispose();

		Layers layers = new Layers();
		layers.tint = argb;
		return layers;
	}

	private static Layers renderArrow(int size, boolean outline, BorderColor borderColor, int scale, Point hotspot)
	{
		// Geometry is laid out in 1x pixels, then everything is multiplied by scale so 1x and 2x line up exactly
		final double border = outline ? size / 17.0 : 0;
		final double blur = size / 16.0;
		final double shadowDrop = size / 20.0;
		final int pad = (int) Math.ceil(blur * 2) + 1;
		final double unit = size / ARROW_HEIGHT;
		final int w1 = (int) Math.ceil(ARROW_WIDTH * unit) + pad * 2;
		final int h1 = size + pad * 2 + (int) Math.ceil(shadowDrop);
		final int w = w1 * scale;
		final int h = h1 * scale;

		Path2D.Double arrow = new Path2D.Double();
		arrow.moveTo(ARROW_X[0], ARROW_Y[0]);
		for (int i = 1; i < ARROW_X.length; i++)
		{
			arrow.lineTo(ARROW_X[i], ARROW_Y[i]);
		}
		arrow.closePath();
		AffineTransform tx = new AffineTransform();
		tx.scale(scale, scale);
		tx.translate(pad, pad);
		tx.scale(unit, unit);
		final Shape outer = tx.createTransformedShape(arrow);

		// The colored fill is the outline inset by the border width; the border is the full outline beneath it,
		// traced with a hairline round stroke to soften the corners slightly like macOS does
		Shape fill = outer;
		if (outline)
		{
			Area inset = new Area(outer);
			inset.subtract(new Area(new BasicStroke((float) (border * 2 * scale)).createStrokedShape(outer)));
			fill = inset;
		}
		final BasicStroke soften = new BasicStroke((float) (0.6 * scale), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

		Layers layers = new Layers();

		// Soft drop shadow of the whole silhouette, then the border on top of it
		final boolean shadow = !outline || borderColor.isShadow();
		Graphics2D g;
		if (shadow)
		{
			BufferedImage silhouette = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			g = antialiased(silhouette);
			g.setColor(SHADOW);
			g.translate(0, shadowDrop * scale);
			g.fill(outer);
			g.dispose();
			layers.under = blur(silhouette, (int) Math.round(blur * scale));
		}
		else
		{
			layers.under = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		}

		if (outline)
		{
			g = antialiased(layers.under);
			g.setColor(borderColor.getColor());
			g.fill(outer);
			if (borderColor.isShadow())
			{
				g.setStroke(soften);
				g.draw(outer);
			}
			g.dispose();
		}

		// The fill is drawn white so the brightness-based recolor turns it fully saturated
		layers.tint = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		g = antialiased(layers.tint);
		g.setColor(Color.WHITE);
		g.fill(fill);
		if (!outline)
		{
			g.setStroke(soften);
			g.draw(fill);
		}
		g.dispose();

		hotspot.setLocation(pad, pad);
		return layers;
	}

	private static Graphics2D antialiased(BufferedImage img)
	{
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		return g;
	}

	private static BufferedImage blur(BufferedImage img, int radius)
	{
		if (radius < 1)
		{
			return img;
		}

		int n = radius * 2 + 1;
		float[] row = new float[n];
		Arrays.fill(row, 1f / n);
		// Two separable box passes approximate a gaussian
		BufferedImage out = img;
		for (int pass = 0; pass < 2; pass++)
		{
			out = new ConvolveOp(new Kernel(n, 1, row), ConvolveOp.EDGE_NO_OP, null).filter(out, null);
			out = new ConvolveOp(new Kernel(1, n, row), ConvolveOp.EDGE_NO_OP, null).filter(out, null);
		}
		return out;
	}
}

package com.rgbcursor;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(RgbCursorConfig.GROUP)
public interface RgbCursorConfig extends Config
{
	String GROUP = "rgbcursor";

	@ConfigSection(
		name = "Mouse trail",
		description = "Rainbow trail that follows the mouse",
		position = 10
	)
	String trailSection = "trail";

	@ConfigItem(
		keyName = "shape",
		name = "Shape",
		description = "Which cursor to color; image shapes are recolored by their brightness",
		position = 0
	)
	default CursorShape shape()
	{
		return CursorShape.ARROW;
	}

	@ConfigItem(
		keyName = "effect",
		name = "Effect",
		description = "How the cursor colors animate",
		position = 1
	)
	default RgbCursorEffect effect()
	{
		return RgbCursorEffect.RAINBOW;
	}

	@Range(min = 1, max = 30)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "cycleSeconds",
		name = "Cycle time",
		description = "Seconds for one full trip around the color wheel",
		position = 2
	)
	default int cycleSeconds()
	{
		return 3;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "saturation",
		name = "Saturation",
		description = "Color intensity; 0% is plain white",
		position = 3
	)
	default int saturation()
	{
		return 100;
	}

	@Range(min = 12, max = 48)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "arrowSize",
		name = "Arrow size",
		description = "Height of the arrow; 17 matches the default macOS pointer (image shapes keep their own size)",
		position = 4
	)
	default int arrowSize()
	{
		return 17;
	}

	@ConfigItem(
		keyName = "outline",
		name = "Border",
		description = "Give the arrow a thin border like the native macOS pointer",
		position = 5
	)
	default boolean outline()
	{
		return true;
	}

	@ConfigItem(
		keyName = "borderColor",
		name = "Border color",
		description = "Color of the arrow's border",
		position = 6
	)
	default BorderColor borderColor()
	{
		return BorderColor.WHITE;
	}

	@ConfigItem(
		keyName = "cursorEnabled",
		name = "Color cursor",
		description = "Replace the mouse pointer with an animated RGB arrow",
		position = -1
	)
	default boolean cursorEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trailEnabled",
		name = "Enable trail",
		description = "Draw a rainbow trail behind the mouse",
		position = 0,
		section = trailSection
	)
	default boolean trailEnabled()
	{
		return true;
	}

	@Range(min = 50, max = 2000)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "trailDuration",
		name = "Trail length",
		description = "How long each part of the trail lingers before fading out",
		position = 1,
		section = trailSection
	)
	default int trailDuration()
	{
		return 350;
	}

	@Range(min = 1, max = 20)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "trailWidth",
		name = "Trail width",
		description = "Thickness of the trail at the cursor end",
		position = 2,
		section = trailSection
	)
	default int trailWidth()
	{
		return 5;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "trailRainbowSpread",
		name = "Rainbow spread",
		description = "How much of the color wheel the trail spans from head to tail",
		position = 3,
		section = trailSection
	)
	default int trailRainbowSpread()
	{
		return 60;
	}
}

package com.rgbcursor;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.awt.Cursor;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientUI;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "RGB Cursor",
	description = "Animated rainbow mouse cursor and trail. Disable the Custom Cursor plugin while using this.",
	tags = {"cursor", "rgb", "rainbow", "mouse", "trail"}
)
public class RgbCursorPlugin extends Plugin
{
	@Inject
	private ClientUI clientUI;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RgbTrailOverlay trailOverlay;

	@Inject
	private RgbCursorConfig config;

	private static final Set<String> CURSOR_KEYS = ImmutableSet.of(
		"cursorEnabled", "shape", "effect", "cycleSeconds", "saturation", "arrowSize", "outline", "borderColor");

	private final long startNanos = System.nanoTime();

	// Swing state below is only touched on the event dispatch thread
	private Timer timer;
	private Cursor[] frames;
	private int shownFrame = -1;

	@Override
	protected void startUp()
	{
		overlayManager.add(trailOverlay);
		SwingUtilities.invokeLater(this::rebuildCursor);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(trailOverlay);
		SwingUtilities.invokeLater(this::stopCursor);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Trail settings are read live each frame; only cursor settings need new frames
		if (RgbCursorConfig.GROUP.equals(event.getGroup()) && CURSOR_KEYS.contains(event.getKey()))
		{
			SwingUtilities.invokeLater(this::rebuildCursor);
		}
	}

	/**
	 * Current position on the color wheel (0..1), shared by the cursor and the trail so they stay in sync.
	 */
	float getHue(long nanos)
	{
		long cycle = config.cycleSeconds() * 1_000_000_000L;
		return (float) ((nanos - startNanos) % cycle) / cycle;
	}

	private void rebuildCursor()
	{
		stopCursor();
		if (!config.cursorEnabled())
		{
			return;
		}

		frames = CursorFrames.build(config.shape(), config.effect(), config.arrowSize(), config.saturation() / 100f, config.outline(), config.borderColor());

		int delay = Math.max(16, config.cycleSeconds() * 1000 / CursorFrames.FRAME_COUNT);
		timer = new Timer(delay, e -> tick());
		timer.setCoalesce(true);
		timer.start();
		tick();
	}

	private void tick()
	{
		if (frames == null)
		{
			return;
		}

		int frame = (int) (getHue(System.nanoTime()) * frames.length) % frames.length;
		if (frame != shownFrame)
		{
			shownFrame = frame;
			clientUI.setCursor(frames[frame]);
		}
	}

	private void stopCursor()
	{
		if (timer == null)
		{
			return;
		}

		timer.stop();
		timer = null;
		frames = null;
		shownFrame = -1;

		// Put back whatever cursor the client had (e.g. one set by Custom Cursor), or the system default
		Cursor previous = clientUI.getDefaultCursor();
		if (previous != null)
		{
			clientUI.setCursor(previous);
		}
		else
		{
			clientUI.resetCursor();
		}
	}

	@Provides
	RgbCursorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RgbCursorConfig.class);
	}
}
